document.querySelectorAll('[data-lab="BM08-I1"]').forEach(root=>{const zh=root.dataset.lang==='zh',q=n=>root.querySelector('[data-field="'+n+'"]');let stage=0;const msg=(z,e)=>zh?z:e;function draw(note){let out='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 260" role="img" aria-label="'+msg('当前末端糖链','Current terminal glycan')+'"><rect width="600" height="260" fill="#f5f9f7"/>';const xs=[80,230,380],names=['Neu5Ac','Gal','GlcNAc'],colors=['#be80bd','#edc45d','#78b4da'];for(let i=0;i<3;i++){const gone=i<stage;out+='<g opacity="'+(gone?'.2':'1')+'">';if(i===0)out+='<path d="M80 72 L112 105 L80 138 L48 105 Z" fill="'+colors[i]+'"/>';else if(i===1)out+='<circle cx="230" cy="105" r="31" fill="'+colors[i]+'"/>';else out+='<rect x="350" y="75" width="60" height="60" fill="'+colors[i]+'"/>';out+='<text x="'+xs[i]+'" y="175" text-anchor="middle" font-size="22" fill="#173f45">'+names[i]+'</text></g>';if(i>=stage&&i<2)out+='<line x1="'+(xs[i]+32)+'" y1="105" x2="'+(xs[i+1]-32)+'" y2="105" stroke="#567c80" stroke-width="3"/><text x="'+(xs[i]+75)+'" y="70" text-anchor="middle" font-size="20">'+(i===0?'α2→3':'β1→4')+'</text>';}out+='<line x1="410" y1="105" x2="475" y2="105" stroke="#567c80" stroke-width="3"/><rect x="475" y="78" width="70" height="54" rx="10" fill="#cbd8d5"/><text x="510" y="113" text-anchor="middle" font-size="24">R</text><text x="300" y="230" text-anchor="middle" font-size="22">'+msg('已切除外侧糖：','Outer residues removed: ')+stage+'/2</text></svg>';q('diagram').innerHTML=out;q('result').textContent=note;}function reset(){stage=0;q('enzyme').value='sial';draw(msg('完整片段。最外层是Neu5Ac，半乳糖尚未成为暴露末端。','Intact fragment. Neu5Ac is outermost; galactose is not yet the exposed terminus.'));}q('apply').addEventListener('click',()=>{const e=q('enzyme').value;if(stage===0&&e==='sial'){stage=1;draw(msg('切去Neu5Ac，Gal现在成为非还原端。下一步可选择β1-4半乳糖苷酶。','Neu5Ac is removed. Gal is now the non-reducing terminus; β1-4 galactosidase can act next.'));}else if(stage===1&&e==='beta'){stage=2;draw(msg('切去Gal，保留GlcNAc–R核心。两次切除支持外侧糖的先后关系。','Gal is removed, leaving the GlcNAc–R core. The two removals establish the order of the outer residues.'));}else if(stage===2){draw(msg('已到本模型保留的核心。所选酶没有本模型中的可切除末端。','The retained core has been reached. The selected enzyme has no cleavable terminus in this model.'));}else if(e==='alpha'){draw(msg('没有切除：这里的Gal通过β键连接，α半乳糖苷酶与该键的构型不匹配。','No removal: Gal is β-linked here, so α-galactosidase does not match its anomeric configuration.'));}else if(stage===0){draw(msg('没有切除：Gal仍被外层Neu5Ac覆盖，尚不是该外切酶需要的暴露末端。','No removal: outer Neu5Ac still caps Gal, so Gal is not the exposed terminus required by this exoglycosidase.'));}else{draw(msg('没有切除：Neu5Ac已经移除，当前末端是Gal。','No removal: Neu5Ac has already been removed; the current terminus is Gal.'));}});q('reset').addEventListener('click',reset);reset();});